WITH mods AS (SELECT cr, section_id FROM cr_modifies_section UNION SELECT cr, section_id FROM section_modified_by), packs AS (SELECT cr, pack_id FROM cr_in_pack UNION SELECT cr, pack_id FROM pack_member), pk AS (SELECT id, tsg_number FROM cr_pack WHERE pack_number = '{ANCHOR}' OR id = '{ANCHOR}'), base AS (SELECT DISTINCT COALESCE(c.number, c.id) AS document, s.spec AS spec, s.release AS release, s.clause AS clause FROM pk JOIN packs p ON p.pack_id = pk.id JOIN document c ON c.id = p.cr JOIN mods mc ON mc.cr = c.id JOIN section s ON s.id = mc.section_id AND ltrim(lower(trim(s.release)),'release-_ v') = ltrim(lower(trim(c.target_release)),'release-_ v') WHERE ltrim(lower(trim(c.target_release)),'release-_ v') IN ('17') AND EXISTS (SELECT 1 FROM disposition dq JOIN resolution rq ON rq.id = dq.resolution_id JOIN meeting mq ON mq.id = rq.meeting_id WHERE dq.target = c.id AND replace(replace(replace(replace(lower(trim(dq.evidence_status)),'-',''),'_',''),' ',''),'#','') = 'sourceverified' AND replace(replace(replace(replace(lower(trim(dq.scope)),'-',''),'_',''),' ',''),'#','') IN ('wholedocument','document','wholedoc','entiredocument','fulldocument') AND replace(replace(replace(replace(lower(trim(mq.wg)),'-',''),'_',''),' ',''),'#','') IN ('ran2','r2','ranwg2','tsgranwg2','tsgr2','wg2'))) SELECT DISTINCT b.document AS document, b.spec AS specification, b.clause AS clause FROM base b WHERE NOT EXISTS (SELECT 1 FROM (SELECT 1) z JOIN section s2 ON s2.spec = b.spec AND s2.release = b.release AND s2.clause = b.clause JOIN mods m2 ON m2.section_id = s2.id JOIN document c2 ON c2.id = m2.cr AND ltrim(lower(trim(c2.target_release)),'release-_ v') = ltrim(lower(trim(b.release)),'release-_ v') JOIN packs p2 ON p2.cr = c2.id JOIN cr_pack cp2 ON cp2.id = p2.pack_id JOIN pk ON cp2.tsg_number < pk.tsg_number)
